var t=[{title:`Combien de temps dure la récupération`,text:`Cela dépend de l’exercice, du volume total, de l’intensité, du sommeil, de la forme et de la familiarité avec le travail. Après une séance difficile pour un grand groupe musculaire, environ 48–72 heures avant une autre séance tout aussi difficile est un repère de planification courant. C’est une indication, et certaines personnes ont besoin de plus ou de moins.`},{title:`Signes que vous n’avez pas récupéré`,text:`Des courbatures qui durent plus longtemps que d’habitude, moins de répétitions à la même charge, des jambes lourdes, une faible motivation et des changements dans votre technique peuvent tous indiquer trop de fatigue. Une mauvaise séance ne prouve pas un surentraînement. Cherchez des tendances sur plusieurs séances, surtout accompagnées de mauvais sommeil, de maladie ou de stress supplémentaire dans le reste de votre vie.`},{title:`Répartissez le travail difficile`,text:`Une semaine type peut comprendre de la force sur tout le corps le lundi et le jeudi, avec des marches faciles les autres jours. S’entraîner plus souvent en force peut fonctionner quand vous répartissez les exercices ou les groupes musculaires sur la semaine et que vous gardez le volume sous contrôle. Du cardio facile ou de la mobilité un jour sans musculation s’accorde généralement bien avec la récupération.`},{title:`Aidez votre corps à s’adapter`,text:`Visez un sommeil régulier, assez de nourriture et d’eau, de petites augmentations d’entraînement et des jours de repos quand vous en avez besoin. Les courbatures ne sont pas une note sur la qualité de la séance. Si vos performances continuent de baisser, réduisez le volume, choisissez des variantes plus faciles ou ajoutez du temps de récupération. N’augmentez pas l’intensité pour compenser.`},{title:`Avec TrainUp`,text:`Après chaque séance, évaluez votre effort et signalez toute douleur ou gêne. Quand vous régénérez le programme, TrainUp examine au moins 3 séances. Toute douleur récente exclut une augmentation. Si 2 de vos 3 dernières séances ont été très difficiles (RPE 9 ou plus) ou terminées à moins de 60 %, le programme suivant est plus facile. Historique affiche votre effort moyen et un graphique sur 4 semaines. Si des symptômes graves persistent, demandez un avis médical.`}];var r=[{label:`Prise de position 2026 de l’ACSM`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026 : dosage de l’exercice, récupération et progression`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`NHS : courbatures musculaires d’apparition retardée`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`}];var a={sections:t,sources:r};export{a as default,t as sections,r as sources};